/** JSON that keeps `undefined` (as ∅) and Maps, and names each PR by `owner/name#n`. */
function show(value: unknown): string {
  return JSON.stringify(value, (_key, v: unknown) => {
    if (v === undefined) return '∅'
    if (v instanceof Map) return { map: [...v] }
    if (typeof v === 'object' && v !== null && 'checks' in v && 'url' in v && 'repo' in v && 'number' in v) return `${String(v.repo)}#${String(v.number)}`
    return v
  })
}

/** Every store write the stage saw, in order, with the value it holds now. */
const written = (s: Stage): string => show(s.setKeys.map((k) => [k, s.saved.get(k)]))

