// ── drawing to text ──────────────────────────────────────────────────────────────────────────

function isElement(v: unknown): v is RenderElement {
  return typeof v === 'object' && v !== null && 'type' in v
}
function nodes(c: unknown): RenderNode[] {
  if (Array.isArray(c)) return c.flatMap(nodes)
  if (typeof c === 'string') return [c]
  if (typeof c === 'number') return [String(c)]
  return isElement(c) ? [c] : []
}
function scalars(props: object): Record<string, string | number | boolean> {
  return Object.fromEntries(Object.entries(props).filter((e): e is [string, string | number | boolean] => ['string', 'number', 'boolean'].includes(typeof e[1])))
}

const EL: Parameters<typeof drawCockpit>[0] = {
  Box: (p) => ({ type: 'Box', props: scalars(p), children: nodes(p.children) }),
  Text: (p) => ({ type: 'Text', props: scalars(p), children: nodes(p.children) }),
  Button: (p) => ({ type: 'Button', props: { key: p.key ?? '', label: p.label ?? '' }, press: { plugin: 'pin', handle: 0 } }),
}

/** One row on one line, its cells split by `|`; a column's parts split by `/`. */
function inline(n: RenderNode): string {
  if (typeof n === 'string') return n
  if (n.type === 'Button') return `[${n.props.label}]`
  if (n.type === 'Box') return (n.children ?? []).map(inline).join(n.props?.flexDirection === 'row' ? ' | ' : ' / ')
  if (n.type === 'Text') return (n.children ?? []).map(inline).join('')
  return `<${n.type}>`
}
function lines(n: RenderNode): string[] {
  if (typeof n !== 'string' && n.type === 'Box' && n.props?.flexDirection !== 'row') return (n.children ?? []).flatMap(lines)
  return [inline(n)]
}

function tabText(board: Board, tab: 'work' | 'prs'): string {
  return lines(drawCockpit(EL, board, { tab, selected: undefined, selectedPr: undefined, checks: undefined }, 80, () => undefined)).join('\n')
}

