  await start($)
  await cockpit($)
  const ui = await $.ui.mount(PANE)
  const got = { work: lines(await ui.drawn()).join('\n'), after: '', facts: '' }
  s.inbox.delete('THV-1041.md')
  await s.clock.advance(1000)
